const fs = require('fs');

(function main() {
  const buf = fs.readFileSync(0, 'utf8');
  const len = buf.length;
  let pos = 0;

  function readInt() {
    while (pos < len) {
      const c = buf.charCodeAt(pos);
      if (c >= 48 && c <= 57) break;
      pos++;
    }
    let x = 0;
    while (pos < len) {
      const c = buf.charCodeAt(pos);
      if (c < 48 || c > 57) break;
      x = x * 10 + (c - 48);
      pos++;
    }
    return x;
  }

  const n = readInt();
  const a = new Float64Array(n);
  for (let k = 0; k < n; k++) a[k] = readInt();

  // Dois ponteiros: cada contração corresponde a estender um bloco.
  // O resultado final é obtido particionando a lista em blocos contíguos
  // cujas somas formam um palíndromo. O número de contrações é N - nº de blocos.
  // Estratégia gulosa ótima: compare as somas correntes dos blocos das pontas;
  // se iguais, fixe os dois blocos; se menores/maiores, mescle o lado menor
  // com o vizinho interno (conta 1 operação). Como todos os valores são
  // positivos, essa gulosa maximiza o número de blocos.

  let ops = 0;
  let i = 0, j = n - 1;
  while (i < j) {
    const lv = a[i], rv = a[j];
    if (lv === rv) {
      i++;
      j--;
    } else {
      ops++;
      if (lv < rv) {
        a[i + 1] += lv;
        i++;
      } else {
        a[j - 1] += rv;
        j--;
      }
    }
  }

  process.stdout.write(ops + '\n');
})();
